{"command":"python3 -c '
import pty, os, subprocess

cmd_file = "/tmp/outcmd_test"
if os.path.exists(cmd_file): os.remove(cmd_file)

master, slave = pty.openpty()
proc = subprocess.Popen(["./executable", "--outcmd", cmd_file, "--cmd", "website;:cd"], stdin=slave, stdout=slave, stderr=slave, close_fds=True)
os.close(slave)
output = b""
while True:
    try:
        data = os.read(master, 1024)
        if not data: break
        output += data
    except OSError:
        break
os.close(master)
proc.wait()
print(f"returncode: {proc.returncode}")
if os.path.exists(cmd_file):
    print("outcmd content:", open(cmd_file).read())
else:
    print("outcmd file not created")
'"}

