{"command":"cat <<'EOF' > src/conf.rs
use std::fs;
use std::path::{Path, PathBuf};
use crate::resources;

pub fn get_config_dir() -> PathBuf {
    if let Ok(dir) = std::env::var("BROOT_CONFIG_DIR") {
        return PathBuf::from(dir);
    }
    if let Some(mut dir) = dirs::config_dir() {
        dir.push("broot");
        dir
    } else {
        PathBuf::from("~/.config/broot")
    }
}

pub fn write_default_conf(target_dir: &Path) -> std::io::Result<()> {
    fs::create_dir_all(target_dir)?;
    fs::write(target_dir.join("conf.hjson"), resources::CONF_HJSON)?;
    fs::write(target_dir.join("verbs.hjson"), resources::VERBS_HJSON)?;

    let skins_dir = target_dir.join("skins");
    fs::create_dir_all(&skins_dir)?;
    for (name, content) in resources::SKINS {
        fs::write(skins_dir.join(name), content)?;
    }
    Ok(())
}

pub fn ensure_default_config() -> std::io::Result<PathBuf> {
    let conf_dir = get_config_dir();
    let main_conf = conf_dir.join("conf.hjson");
    if !main_conf.exists() {
        write_default_conf(&conf_dir)?;
        println!("New Configuration files written in {:?}.", conf_dir.display());
        println!("You should have a look at them: their comments will help you configure broot.");
        println!("You should especially set up your favourite editor in verbs.hjson.");
    }
    Ok(conf_dir)
}
EOF"}

