use std::fs;
use std::path::PathBuf;
use crate::resources;
use crate::conf;

pub fn print_shell_function(shell: &str) -> i32 {
    match shell {
        "bash" | "zsh" => print!("{}", resources::SHELL_BASH),
        "fish" => print!("{}", resources::SHELL_FISH),
        "nushell" => print!("{}", resources::SHELL_NUSHELL),
        "powershell" => print!("{}", resources::SHELL_POWERSHELL),
        _ => {
            eprintln!("Unknown shell: {shell}");
            return 1;
        }
    }
    0
}

fn remove_and_log(path: &PathBuf) {
    if path.exists() {
        let _ = fs::remove_file(path);
        println!("Removing \x1b[48;5;234m\x1b[38;5;250m{}\x1b[49m\x1b[39m.", path.display());
    }
}

pub fn set_install_state(state: &str) -> i32 {
    let mut launcher_dir = conf::get_config_dir();
    launcher_dir.push("launcher");
    if let Err(e) = fs::create_dir_all(&launcher_dir) {
        eprintln!("Error creating directory {:?}: {}", launcher_dir, e);
        return 1;
    }

    let installed_file = launcher_dir.join("installed-v4");
    let refused_file = launcher_dir.join("refused");

    match state {
        "installed" => {
            remove_and_log(&installed_file);
            remove_and_log(&refused_file);
            let _ = fs::write(&installed_file, "");
            0
        }
        "refused" => {
            remove_and_log(&installed_file);
            remove_and_log(&refused_file);
            let _ = fs::write(&refused_file, "");
            0
        }
        "undefined" => {
            remove_and_log(&installed_file);
            remove_and_log(&refused_file);
            0
        }
        _ => {
            eprintln!("Invalid install state: {state}");
            1
        }
    }
}

pub fn install() -> i32 {
    println!(" You requested a clean (re)install.");
    let shell = std::env::var("SHELL").unwrap_or_else(|_| "bash".to_string());
    let shell_name = if shell.contains("zsh") {
        "zsh"
    } else if shell.contains("fish") {
        "fish"
    } else {
        "bash"
    };

    let mut local_share = dirs::data_dir().unwrap_or_else(|| PathBuf::from("~/.local/share"));
    local_share.push("broot/launcher");
    local_share.push(shell_name);
    let script_file = local_share.join("1");

    if script_file.exists() {
        println!("Removing \x1b[48;5;234m\x1b[38;5;250m{}\x1b[49m\x1b[39m.", script_file.display());
        let _ = fs::remove_file(&script_file);
    }

    let _ = fs::create_dir_all(&local_share);
    let content = match shell_name {
        "fish" => resources::SHELL_FISH,
        _ => resources::SHELL_BASH,
    };
    println!("Writing \x1b[38;5;13mbr\x1b[0m shell function in \x1b[48;5;234m\x1b[38;5;250m{}\x1b[49m\x1b[39m.", script_file.display());
    let _ = fs::write(&script_file, content);

    let mut conf_launcher = conf::get_config_dir();
    conf_launcher.push("launcher");
    conf_launcher.push(shell_name);
    let link_file = conf_launcher.join("br");

    if link_file.exists() || fs::symlink_metadata(&link_file).is_ok() {
        println!("Removing \x1b[48;5;234m\x1b[38;5;250m{}\x1b[49m\x1b[39m.", link_file.display());
        let _ = fs::remove_file(&link_file);
    }

    let _ = fs::create_dir_all(&conf_launcher);
    println!("Creating link from \x1b[48;5;234m\x1b[38;5;250m{}\x1b[49m\x1b[39m to \x1b[48;5;234m\x1b[38;5;250m{}\x1b[49m\x1b[39m.", link_file.display(), script_file.display());
    #[cfg(unix)]
    let _ = std::os::unix::fs::symlink(&script_file, &link_file);

    let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("~"));
    let rc_file = match shell_name {
        "zsh" => home.join(".zshrc"),
        "fish" => home.join(".config/fish/config.fish"),
        _ => home.join(".bashrc"),
    };

    let source_line = format!("\nsource {}", link_file.display());
    if rc_file.exists() {
        if let Ok(rc_content) = fs::read_to_string(&rc_file) {
            if rc_content.contains(&link_file.to_string_lossy().to_string()) {
                println!("\x1b[48;5;234m\x1b[38;5;250m{}\x1b[49m\x1b[39m already patched, no change made.", rc_file.display());
            } else {
                let mut f = fs::OpenOptions::new().append(true).open(&rc_file).unwrap();
                use std::io::Write;
                let _ = writeln!(f, "{}", source_line);
                println!("\x1b[48;5;234m\x1b[38;5;250m{}\x1b[49m\x1b[39m successfully patched, you can make the function immediately available with \x1b[48;5;234m\x1b[38;5;250msource \x1b[49m\x1b[39m\x1b[48;5;234m\x1b[38;5;250m{}\x1b[49m\x1b[39m", rc_file.display(), rc_file.display());
            }
        }
    }

    set_install_state("installed");

    println!("\nThe \x1b[1mbr\x1b[0m function has been successfully installed.");
    println!("You may have to restart your shell or source your \nshell init files.");
    println!("Afterwards, you should start broot with \x1b[48;5;234m\x1b[38;5;250mbr\x1b[49m\x1b[39m in \norder to use its full power.\n");

    0
}
EOF"}

