use std::fs;
use std::path::{Path, PathBuf};
use std::time::SystemTime;
use walkdir::WalkDir;

#[derive(Debug, Clone)]
pub struct TreeOptions {
    pub show_hidden: bool,
    pub show_git_ignored: bool,
    pub only_folders: bool,
    pub show_dates: bool,
    pub show_permissions: bool,
    pub show_sizes: bool,
    pub max_depth: Option<usize>,
    pub sort_mode: SortMode,
    pub trim_root: bool,
}

impl Default for TreeOptions {
    fn default() -> Self {
        Self {
            show_hidden: false,
            show_git_ignored: false,
            only_folders: false,
            show_dates: false,
            show_permissions: false,
            show_sizes: false,
            max_depth: None,
            sort_mode: SortMode::None,
            trim_root: false,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SortMode {
    None,
    BySize,
    ByDate,
    ByCount,
    ByTypeDirsFirst,
    ByTypeDirsLast,
}

#[derive(Debug, Clone)]
pub struct TreeLine {
    pub path: PathBuf,
    pub name: String,
    pub is_dir: bool,
    pub depth: usize,
    pub size: u64,
    pub modified: Option<SystemTime>,
    pub permissions: String,
    pub direct_match: bool,
    pub sub_match: bool,
}

pub struct Tree {
    pub root: PathBuf,
    pub options: TreeOptions,
    pub lines: Vec<TreeLine>,
    pub selection: usize,
}

impl Tree {
    pub fn new(root: PathBuf, options: TreeOptions) -> Self {
        let mut tree = Self {
            root,
            options,
            lines: Vec::new(),
            selection: 0,
        };
        tree.refresh("");
        tree
    }

    pub fn refresh(&mut self, filter: &str) {
        let root = match fs::canonicalize(&self.root) {
            Ok(p) => p,
            Err(_) => self.root.clone(),
        };

        let mut lines = Vec::new();

        // Recursively gather lines
        Self::scan_dir(&root, 0, filter, &self.options, &mut lines);

        if !filter.is_empty() {
            // Filter lines: keep matching items or items with sub_matches
            lines.retain(|line| line.direct_match || line.sub_match);
        }

        // Apply sorting if needed
        match self.options.sort_mode {
            SortMode::BySize => {
                lines.sort_by(|a, b| b.size.cmp(&a.size));
            }
            SortMode::ByDate => {
                lines.sort_by(|a, b| b.modified.cmp(&a.modified));
            }
            SortMode::ByTypeDirsFirst => {
                lines.sort_by(|a, b| match (a.is_dir, b.is_dir) {
                    (true, false) => std::cmp::Ordering::Less,
                    (false, true) => std::cmp::Ordering::Greater,
                    _ => a.name.to_lowercase().cmp(&b.name.to_lowercase()),
                });
            }
            SortMode::ByTypeDirsLast => {
                lines.sort_by(|a, b| match (a.is_dir, b.is_dir) {
                    (true, false) => std::cmp::Ordering::Greater,
                    (false, true) => std::cmp::Ordering::Less,
                    _ => a.name.to_lowercase().cmp(&b.name.to_lowercase()),
                });
            }
            _ => {}
        }

        self.lines = lines;
        if self.selection >= self.lines.len() && !self.lines.is_empty() {
            self.selection = self.lines.len() - 1;
        }
    }

    fn scan_dir(
        dir: &Path,
        depth: usize,
        filter: &str,
        options: &TreeOptions,
        out: &mut Vec<TreeLine>,
    ) -> bool {
        if let Some(max_d) = options.max_depth {
            if depth > max_d {
                return false;
            }
        }

        let entries = match fs::read_dir(dir) {
            Ok(e) => e,
            Err(_) => return false,
        };

        let mut items = Vec::new();
        for entry in entries.flatten() {
            let path = entry.path();
            let name = entry.file_name().to_string_lossy().to_string();

            if !options.show_hidden && name.starts_with('.') {
                continue;
            }

            let metadata = entry.metadata().ok();
            let is_dir = metadata.as_ref().map(|m| m.is_dir()).unwrap_or(false);

            if options.only_folders && !is_dir {
                continue;
            }

            let size = metadata.as_ref().map(|m| m.len()).unwrap_or(0);
            let modified = metadata.as_ref().and_then(|m| m.modified().ok());
            let permissions = format_permissions(&metadata);

            let filter_lower = filter.to_lowercase();
            let direct_match = filter.is_empty() || name.to_lowercase().contains(&filter_lower);

            items.push((path, name, is_dir, size, modified, permissions, direct_match));
        }

        // Sort items by name
        items.sort_by(|a, b| a.1.to_lowercase().cmp(&b.1.to_lowercase()));

        let mut any_match = false;

        for (path, name, is_dir, size, modified, permissions, direct_match) in items {
            let start_idx = out.len();

            let mut sub_match = false;
            if is_dir {
                sub_match = Self::scan_dir(&path, depth + 1, filter, options, out);
            }

            let is_match = direct_match || sub_match;
            if filter.is_empty() || is_match {
                any_match = true;
                // Insert entry before its sub-children
                out.insert(
                    start_idx,
                    TreeLine {
                        path,
                        name,
                        is_dir,
                        depth,
                        size,
                        modified,
                        permissions,
                        direct_match,
                        sub_match,
                    },
                );
            }
        }

        any_match
    }

    pub fn selected_item(&self) -> Option<&TreeLine> {
        self.lines.get(self.selection)
    }
}

fn format_permissions(metadata: &Option<fs::Metadata>) -> String {
    #[cfg(unix)]
    if let Some(m) = metadata {
        use std::os::unix::fs::PermissionsExt;
        let mode = m.permissions().mode();
        let user = format!("{}{}{}", 
            if mode & 0o400 != 0 { 'r' } else { '-' },
            if mode & 0o200 != 0 { 'w' } else { '-' },
            if mode & 0o100 != 0 { 'x' } else { '-' });
        let group = format!("{}{}{}", 
            if mode & 0o040 != 0 { 'r' } else { '-' },
            if mode & 0o020 != 0 { 'w' } else { '-' },
            if mode & 0o010 != 0 { 'x' } else { '-' });
        let other = format!("{}{}{}", 
            if mode & 0o004 != 0 { 'r' } else { '-' },
            if mode & 0o002 != 0 { 'w' } else { '-' },
            if mode & 0o001 != 0 { 'x' } else { '-' });
        return format!("{}{}{}", user, group, other);
    }
    "rwxr-xr-x".to_string()
}
