#[derive(Debug, Clone)]
pub enum ExitAction {
    None,
    Quit,
    PrintPath(PathBuf),
    PrintRelativePath(PathBuf, PathBuf), // (full_path, root_path)
    PrintTree(String),
    OutCmd(String),
}

pub fn execute_cmd_sequence(
    commands: &str,
    tree: &mut Tree,
    outcmd_path: Option<&PathBuf>,
    verb_output_path: Option<&PathBuf>,
) -> Result<ExitAction, String> {
    let mut exit_action = ExitAction::None;
    let parts: Vec<&str> = commands.split(';').collect();

    for raw_cmd in parts {
        let cmd = raw_cmd.trim();
        if cmd.is_empty() {
            continue;
        }

        if cmd.starts_with(':') {
            // Internal or defined verb
            let verb_str = &cmd[1..];
            let mut verb_parts = verb_str.split_whitespace();
            let verb_name = verb_parts.next().unwrap_or("");
            let arg = verb_parts.collect::<Vec<&str>>().join(" ");

            match verb_name {
                "quit" | "q" => {
                    return Ok(ExitAction::Quit);
                }
                "print_path" | "pp" => {
                    if let Some(selected) = tree.selected_item() {
                        return Ok(ExitAction::PrintPath(selected.path.clone()));
                    } else {
                        return Ok(ExitAction::PrintPath(tree.root.clone()));
                    }
                }
                "print_relative_path" | "prp" => {
                    if let Some(selected) = tree.selected_item() {
                        return Ok(ExitAction::PrintRelativePath(selected.path.clone(), tree.root.clone()));
                    } else {
                        return Ok(ExitAction::PrintRelativePath(tree.root.clone(), tree.root.clone()));
                    }
                }
                "focus" => {
                    if !arg.is_empty() {
                        let target = if arg == ".." {
                            tree.root.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| tree.root.clone())
                        } else {
                            tree.root.join(&arg)
                        };
                        tree.root = target;
                    } else if let Some(selected) = tree.selected_item() {
                        if selected.is_dir {
                            tree.root = selected.path.clone();
                        } else if let Some(parent) = selected.path.parent() {
                            tree.root = parent.to_path_buf();
                        }
                    }
                    tree.refresh("");
                }
                "parent" | "up_tree" => {
                    if let Some(parent) = tree.root.parent() {
                        tree.root = parent.to_path_buf();
                        tree.refresh("");
                    }
                }
                "cd" => {
                    let target_dir = if let Some(selected) = tree.selected_item() {
                        if selected.is_dir {
                            selected.path.clone()
                        } else {
                            selected.path.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| tree.root.clone())
                        }
                    } else {
                        tree.root.clone()
                    };
                    let cd_cmd = format!("cd {:?}", target_dir.display());
                    if let Some(outcmd) = outcmd_path {
                        let _ = std::fs::write(outcmd, &cd_cmd);
                    }
                    return Ok(ExitAction::OutCmd(cd_cmd));
                }
                "line_down" => {
                    let count = arg.parse::<usize>().unwrap_or(1);
                    if !tree.lines.is_empty() {
                        tree.selection = (tree.selection + count).min(tree.lines.len() - 1);
                    }
                }
                "line_up" => {
                    let count = arg.parse::<usize>().unwrap_or(1);
                    if tree.selection >= count {
                        tree.selection -= count;
                    } else {
                        tree.selection = 0;
                    }
                }
                "select_first" => {
                    tree.selection = 0;
                }
                "select_last" => {
                    if !tree.lines.is_empty() {
                        tree.selection = tree.lines.len() - 1;
                    }
                }
                "toggle_hidden" => {
                    tree.options.show_hidden = !tree.options.show_hidden;
                    tree.refresh("");
                }
                "toggle_ignore" => {
                    tree.options.show_git_ignored = !tree.options.show_git_ignored;
                    tree.refresh("");
                }
                "toggle_files" => {
                    tree.options.only_folders = !tree.options.only_folders;
                    tree.refresh("");
                }
                "toggle_perm" => {
                    tree.options.show_permissions = !tree.options.show_permissions;
                }
                "toggle_sizes" => {
                    tree.options.show_sizes = !tree.options.show_sizes;
                }
                "toggle_dates" => {
                    tree.options.show_dates = !tree.options.show_dates;
                }
                "sort_by_size" | "ss" => {
                    tree.options.sort_mode = SortMode::BySize;
                    tree.refresh("");
                }
                "sort_by_date" | "sd" => {
                    tree.options.sort_mode = SortMode::ByDate;
                    tree.refresh("");
                }
                "sort_by_type" | "st" => {
                    tree.options.sort_mode = SortMode::ByTypeDirsFirst;
                    tree.refresh("");
                }
                "no_sort" | "ns" => {
                    tree.options.sort_mode = SortMode::None;
                    tree.refresh("");
                }
                _ => {
                    return Err(format!("Unknown verb: :{verb_name}"));
                }
            }
        } else {
            // Search filter query
            tree.refresh(cmd);
            if !tree.lines.is_empty() {
                tree.selection = 0;
            }
        }
    }

    Ok(exit_action)
}
EOF"}

