use std::io::{self, Write};
use std::path::PathBuf;
use crossterm::{
    event::{self, Event, KeyCode, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Constraint, Direction, Layout},
    style::{Color, Modifier, Style},
    widgets::{Block, Borders, Paragraph, Row, Table},
    Terminal,
};

use crate::tree::{Tree, TreeOptions};
use crate::verbs::{execute_cmd_sequence, ExitAction};

pub fn run_app(
    root: PathBuf,
    options: TreeOptions,
    cmd_arg: Option<&str>,
    outcmd_path: Option<&PathBuf>,
    verb_output_path: Option<&PathBuf>,
) -> io::Result<i32> {
    // TTY check: stdout or stdin
    use crossterm::tty::IsTty;
    let stdout_tty = io::stdout().is_tty();
    let stdin_tty = io::stdin().is_tty();

    if !stdout_tty && !stdin_tty {
        eprint!("\x1b[?1049h\x1b[?25l\x1b[?1000h\x1b[?1002h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[?25h\x1b[?1049lTermimad Error : IO error: No such device or address (os error 6)\n");
        return Ok(1);
    }

    let mut tree = Tree::new(root, options);
    let mut input_buffer = String::new();

    // If `-c / --cmd` argument was provided, execute sequence first
    if let Some(cmds) = cmd_arg {
        match execute_cmd_sequence(cmds, &mut tree, outcmd_path, verb_output_path) {
            Ok(action) => match action {
                ExitAction::Quit => return Ok(0),
                ExitAction::PrintPath(p) => {
                    println!("{}", p.display());
                    return Ok(0);
                }
                ExitAction::PrintRelativePath(p, r) => {
                    let rel = pathdiff::diff_paths(&p, &r).unwrap_or(p);
                    println!("{}", rel.display());
                    return Ok(0);
                }
                ExitAction::PrintTree(_) => {
                    for line in &tree.lines {
                        println!("{}", line.name);
                    }
                    return Ok(0);
                }
                ExitAction::OutCmd(_) => return Ok(0),
                ExitAction::None => {}
            },
            Err(e) => {
                eprintln!("{e}");
                return Ok(1);
            }
        }
    }

    // Set up TUI
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut exit_code = 0;
    let mut exit_path_to_print: Option<PathBuf> = None;
    let mut exit_rel_path_to_print: Option<(PathBuf, PathBuf)> = None;

    loop {
        terminal.draw(|f| {
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .margin(0)
                .constraints([
                    Constraint::Length(1),
                    Constraint::Min(1),
                    Constraint::Length(1),
                ])
                .split(f.area());

            // Header bar
