    }

    if matches.get_flag("help") {
        print!("{}", resources::HELP_TEXT);
        std::process::exit(0);
    }

    if let Some(shell_name) = matches.get_one::<String>("print-shell-function") {
        let code = shell::print_shell_function(shell_name);
        std::process::exit(code);
    }

    if let Some(conf_path) = matches.get_one::<String>("write-default-conf") {
        if let Err(e) = conf::write_default_conf(&PathBuf::from(conf_path)) {
            eprintln!("Error writing default config: {e}");
            std::process::exit(1);
        }
        std::process::exit(0);
    }

    if let Some(state) = matches.get_one::<String>("set-install-state") {
        let code = shell::set_install_state(state);
        std::process::exit(code);
    }

    if matches.get_flag("install") {
        let code = shell::install();
        std::process::exit(code);
    }

    // Ensure default config exists in ~/.config/broot if missing
    let _ = conf::ensure_default_config();

    let root = matches
        .get_one::<String>("ROOT")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."));

    let mut options = TreeOptions::default();

    if matches.get_flag("hidden") {
        options.show_hidden = true;
    }
    if matches.get_flag("no-hidden") {
        options.show_hidden = false;
    }

    if matches.get_flag("git-ignored") {
        options.show_git_ignored = true;
    }
    if matches.get_flag("no-git-ignored") {
        options.show_git_ignored = false;
    }

    if matches.get_flag("only-folders") {
        options.only_folders = true;
    }
    if matches.get_flag("no-only-folders") {
        options.only_folders = false;
    }

    if matches.get_flag("dates") {
        options.show_dates = true;
    }
    if matches.get_flag("no-dates") {
        options.show_dates = false;
    }

    if matches.get_flag("permissions") {
        options.show_permissions = true;
    }
    if matches.get_flag("no-permissions") {
        options.show_permissions = false;
    }

    if matches.get_flag("sizes") {
        options.show_sizes = true;
    }
    if matches.get_flag("no-sizes") {
        options.show_sizes = false;
    }

    if matches.get_flag("sort-by-size") {
        options.sort_mode = SortMode::BySize;
    } else if matches.get_flag("sort-by-date") {
        options.sort_mode = SortMode::ByDate;
    } else if matches.get_flag("sort-by-type") || matches.get_flag("sort-by-type-dirs-first") {
        options.sort_mode = SortMode::ByTypeDirsFirst;
    } else if matches.get_flag("sort-by-type-dirs-last") {
        options.sort_mode = SortMode::ByTypeDirsLast;
    } else if matches.get_flag("sort-by-count") {
        options.sort_mode = SortMode::ByCount;
    } else if matches.get_flag("no-sort") {
        options.sort_mode = SortMode::None;
    }

    if matches.get_flag("whale-spotting") {
        options.sort_mode = SortMode::BySize;
        options.show_hidden = true;
        options.show_git_ignored = true;
    }

    if let Some(depth_str) = matches.get_one::<String>("max-depth") {
        if let Ok(d) = depth_str.parse::<usize>() {
            options.max_depth = Some(d);
        }
    }

    let cmd_arg = matches.get_one::<String>("cmd").map(|s| s.as_str());
    let outcmd_path = matches.get_one::<String>("outcmd").map(PathBuf::from);
    let verb_output_path = matches.get_one::<String>("verb-output").map(PathBuf::from);

    match app::run_app(root, options, cmd_arg, outcmd_path.as_ref(), verb_output_path.as_ref()) {
        Ok(code) => std::process::exit(code),
        Err(e) => {
            eprintln!("Error: {e}");
            std::process::exit(1);
        }
    }
}
EOF"}

