use std::io;
use std::path::PathBuf;
use crossterm::{
    event::{self, Event, KeyCode, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::CrosstermBackend,
    layout::{Constraint, Direction, Layout},
    style::{Color, Modifier, Style},
    widgets::{Paragraph, Row, Table},
    Terminal,
};

use crate::tree::{Tree, TreeOptions};
use crate::verbs::{execute_cmd_sequence, ExitAction};

pub fn run_app(
    root: PathBuf,
    options: TreeOptions,
    cmd_arg: Option<&str>,
    outcmd_path: Option<&PathBuf>,
    verb_output_path: Option<&PathBuf>,
) -> io::Result<i32> {
    use crossterm::tty::IsTty;
    let stdout_tty = io::stdout().is_tty();
    let stdin_tty = io::stdin().is_tty();

    if !stdout_tty && !stdin_tty {
        eprint!("\x1b[?1049h\x1b[?25l\x1b[?1000h\x1b[?1002h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[?25h\x1b[?1049lTermimad Error : IO error: No such device or address (os error 6)\n");
        return Ok(1);
    }

    let mut tree = Tree::new(root, options);
    let mut input_buffer = String::new();

    if let Some(cmds) = cmd_arg {
        match execute_cmd_sequence(cmds, &mut tree, outcmd_path, verb_output_path) {
            Ok(action) => match action {
                ExitAction::Quit => return Ok(0),
                ExitAction::PrintPath(p) => {
                    println!("{}", p.display());
                    return Ok(0);
                }
                ExitAction::PrintRelativePath(p, r) => {
                    let rel = p.strip_prefix(&r).unwrap_or(&p);
                    println!("{}", rel.display());
                    return Ok(0);
                }
                ExitAction::PrintTree(_) => {
                    for line in &tree.lines {
                        println!("{}", line.name);
                    }
                    return Ok(0);
                }
                ExitAction::OutCmd(_) => return Ok(0),
                ExitAction::None => {}
            },
            Err(e) => {
                eprintln!("{e}");
                return Ok(1);
            }
        }
    }

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut exit_code = 0;
    let mut exit_path_to_print: Option<PathBuf> = None;
    let mut exit_rel_path_to_print: Option<(PathBuf, PathBuf)> = None;

    loop {
        terminal.draw(|f| {
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .margin(0)
                .constraints([
                    Constraint::Length(1),
                    Constraint::Min(1),
                    Constraint::Length(1),
                ])
                .split(f.area());

            let header_text = format!(" {}", tree.root.display());
            let header = Paragraph::new(header_text)
                .style(Style::default().bg(Color::Rgb(60, 60, 60)).fg(Color::Cyan).add_modifier(Modifier::BOLD));
            f.render_widget(header, chunks[0]);

            let mut rows = Vec::new();
            for (idx, line) in tree.lines.iter().enumerate() {
                let indent = "  ".repeat(line.depth);
                let prefix = if line.is_dir { "▶ " } else { "  " };
                let display_name = format!("{indent}{prefix}{}", line.name);

                let mut style = Style::default();
                if idx == tree.selection {
                    style = style.bg(Color::Rgb(50, 50, 50)).add_modifier(Modifier::BOLD);
                }
                if line.is_dir {
                    style = style.fg(Color::Cyan);
                } else {
                    style = style.fg(Color::White);
                }

                rows.push(Row::new(vec![display_name]).style(style));
            }

            let table = Table::new(rows, [Constraint::Percentage(100)]);
            f.render_widget(table, chunks[1]);

            let status_text = format!(" {}", input_buffer);
            let status = Paragraph::new(status_text)
                .style(Style::default().bg(Color::Rgb(30, 30, 30)).fg(Color::Yellow));
            f.render_widget(status, chunks[2]);
        })?;

        if event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Char('q') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        break;
                    }
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                        break;
                    }
                    KeyCode::Esc => {
                        input_buffer.clear();
                        tree.refresh("");
                    }
                    KeyCode::Down => {
                        if !tree.lines.is_empty() {
                            tree.selection = (tree.selection + 1).min(tree.lines.len() - 1);
                        }
                    }
                    KeyCode::Up => {
                        if tree.selection > 0 {
                            tree.selection -= 1;
                        }
                    }
                    KeyCode::Enter => {
                        if input_buffer.starts_with(':') {
                            match execute_cmd_sequence(&input_buffer, &mut tree, outcmd_path, verb_output_path) {
                                Ok(ExitAction::Quit) => break,
                                Ok(ExitAction::PrintPath(p)) => {
                                    exit_path_to_print = Some(p);
                                    break;
                                }
                                Ok(ExitAction::PrintRelativePath(p, r)) => {
                                    exit_rel_path_to_print = Some((p, r));
                                    break;
                                }
                                Ok(ExitAction::PrintTree(_)) => break,
                                Ok(ExitAction::OutCmd(_)) => break,
                                Ok(ExitAction::None) => {}
                                Err(e) => {
                                    eprintln!("{e}");
                                    exit_code = 1;
                                    break;
                                }
                            }
                            input_buffer.clear();
                        } else if let Some(selected) = tree.selected_item() {
                            if selected.is_dir {
                                tree.root = selected.path.clone();
                                input_buffer.clear();
                                tree.refresh("");
                            } else {
                                exit_path_to_print = Some(selected.path.clone());
                                break;
                            }
                        }
                    }
                    KeyCode::Char(c) => {
                        input_buffer.push(c);
                        if !input_buffer.starts_with(':') {
                            tree.refresh(&input_buffer);
                        }
                    }
                    KeyCode::Backspace => {
                        input_buffer.pop();
                        if !input_buffer.starts_with(':') {
                            tree.refresh(&input_buffer);
                        }
                    }
                    _ => {}
                }
            }
        }
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Some(p) = exit_path_to_print {
        println!("{}", p.display());
    } else if let Some((p, r)) = exit_rel_path_to_print {
        let rel = p.strip_prefix(&r).unwrap_or(&p);
        println!("{}", rel.display());
    }

    Ok(exit_code)
}
EOF"}

