                                    break;
                                }
                            }
                            input_buffer.clear();
                        } else if let Some(selected) = tree.selected_item() {
                            if selected.is_dir {
                                tree.root = selected.path.clone();
                                input_buffer.clear();
                                tree.refresh("");
                            } else {
                                exit_path_to_print = Some(selected.path.clone());
                                break;
                            }
                        }
                    }
                    KeyCode::Char(c) => {
                        input_buffer.push(c);
                        if !input_buffer.starts_with(':') {
                            tree.refresh(&input_buffer);
                        }
                    }
                    KeyCode::Backspace => {
                        input_buffer.pop();
                        if !input_buffer.starts_with(':') {
                            tree.refresh(&input_buffer);
                        }
                    }
                    _ => {}
                }
            }
        }
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    if let Some(p) = exit_path_to_print {
        println!("{}", p.display());
    } else if let Some((p, r)) = exit_rel_path_to_print {
        let rel = p.strip_prefix(&r).unwrap_or(&p);
        println!("{}", rel.display());
    }

    Ok(exit_code)
}
